using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using BepInEx;
using ES3Internal;
using HutongGames.PlayMaker;
using HutongGames.PlayMaker.Actions;
using UnityEngine;
using UnityEngine.SceneManagement;
[BepInPlugin("weaponspack.local.harvestchecks","Local Harvest Checks","1.0.0")]
public sealed class HarvestChecks:BaseUnityPlugin {
 const BindingFlags All=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 const string Key="ApocalypterWeaponsPack.BurntCorpses";
 readonly List<GameObject> owned=new List<GameObject>();readonly List<string> failures=new List<string>();int checks;string host;Assembly assembly;Type marker,helper;object pack;Scene fixtureScene;
 object Call(object owner,string name,params object[] args){return owner.GetType().GetMethod(name,All).Invoke(owner,args);}void Set(object owner,string name,object value){owner.GetType().GetField(name,All).SetValue(owner,value);}
 void Check(bool ok,string name){checks++;Logger.LogInfo((ok?"PASS: ":"FAIL: ")+name);if(!ok)failures.Add(name);}
 GameObject Make(string name){var go=new GameObject(name);SceneManager.MoveGameObjectToScene(go,fixtureScene);owned.Add(go);go.SetActive(false);return go;}
 void Mark(GameObject go){go.AddComponent(marker);}
 int Apply(GameObject go){return helper==null?0:(int)helper.GetMethod("Apply",All).Invoke(null,new object[]{go,new Action<string>(s=>Logger.LogInfo("EXPECTED SKIP: "+s))});}
 PlayMakerFSM Fsm(GameObject go,string name,FsmStateAction[] actions){var component=go.AddComponent<PlayMakerFSM>();component.Reset();component.enabled=false;var fsm=new Fsm{Name=name};var state=new FsmState(fsm){Name=name=="Cook"?"spawn":"butcher",Actions=actions};fsm.States=new[]{state};fsm.StartState=state.Name;fsm.SaveActions();component.Fsm=fsm;fsm.Init(component);return component;}
 CreateObject Spawn(GameObject value){return new CreateObject{gameObject=new FsmGameObject{Value=value},parent=new FsmGameObject(),spawnPoint=new FsmGameObject(),position=new FsmVector3{Value=Vector3.zero},rotation=new FsmVector3{Value=Vector3.zero},storeObject=new FsmGameObject()};}
 GameObject Raw(string kind,out GameObject cooked){cooked=Make("meat_"+kind+"_cooked");var raw=Make("meat_"+kind+"_raw");Fsm(raw,"Cook",new FsmStateAction[]{Spawn(cooked)});return raw;}
 CreateObject Action(GameObject corpse){return (CreateObject)corpse.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions[0];}
 GameObject Corpse(string name,GameObject raw,bool mark,long id=12345){var corpse=Make(name);Fsm(corpse,"Carcasse",new FsmStateAction[]{Spawn(raw)});corpse.AddComponent<ES3Prefab>().prefabId=id;if(mark)Mark(corpse);return corpse;}
 void Awake(){host=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Info.Location),"../../.."));try{fixtureScene=SceneManager.CreateScene("FlameHarvestChecks");Run();}catch(Exception e){failures.Add(e.ToString());Logger.LogError(e);}foreach(var go in owned)if(go!=null)DestroyImmediate(go);File.WriteAllText(Path.Combine(host,"result.txt"),(failures.Count==0?"PASS: ":"FAIL: ")+checks+" native harvest checks; failures="+failures.Count+"\n"+string.Join("\n",failures.ToArray()));Application.Quit();}
 void Run(){assembly=Assembly.LoadFrom(Path.Combine(host,"lib/ChainsawPrototype.dll"));marker=assembly.GetType("ChainsawPrototype.FlameBurntCorpse",true);helper=assembly.GetType("ChainsawPrototype.FlameCookedHarvest");var root=Make("InactiveHarvestPack");pack=root.AddComponent(assembly.GetType("ChainsawPrototype.Plugin",true));
  GameObject cooked;var raw=Raw("dog",out cooked);var body=Corpse("Dog_Dead(Clone)100",raw,true);var action=Action(body);var original=action.gameObject;
  Check(Apply(body)==1&&action.gameObject.Value==cooked,"marked corpse harvest selects native cooked equivalent");if(helper==null)return;
  Check(!ReferenceEquals(action.gameObject,original)&&original.Value==raw,"conversion clones constant wrapper and preserves original");Check(Apply(body)==0&&action.gameObject.Value==cooked,"repeated application is idempotent");
  var plain=Corpse("Dog_Dead(Clone)101",raw,false);Check(Apply(plain)==0&&Action(plain).gameObject.Value==raw,"unmarked corpse stays raw");var template=Corpse("Dog_Dead",raw,false);Check(Action(template).gameObject.Value==raw,"native corpse template stays raw");Check(raw.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions[0] is CreateObject&&((CreateObject)raw.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions[0]).gameObject.Value==cooked,"native raw Cook FSM is unchanged");
  foreach(string kind in new[]{"insect","mutant"}){GameObject destination;var source=Raw(kind,out destination);var corpse=Corpse(kind+"_Dead(Clone)102",source,true);Check(Apply(corpse)==1&&Action(corpse).gameObject.Value==destination,"species retains native cooked mapping: "+kind);}
  GameObject coldCooked;var coldRaw=Raw("dog",out coldCooked);var coldState=coldRaw.GetComponent<PlayMakerFSM>().Fsm.States[0];typeof(FsmState).GetField("actions",All).SetValue(coldState,null);typeof(FsmState).GetField("fsm",All).SetValue(coldState,null);var coldBody=Corpse("Cold_Dead(Clone)110",coldRaw,true);Check(Apply(coldBody)==1&&Action(coldBody).gameObject.Value==coldCooked,"unawoken prefab cooking data resolves without shared initialization");Check(coldState.Fsm==null&&!coldState.ActionsLoaded,"cold prefab state stays uninitialized and actions unloaded");
  var nonmeat=Make("mod_custom_loot");Fsm(nonmeat,"Cook",new FsmStateAction[]{Spawn(cooked)});var foreign=Corpse("Foreign_Dead(Clone)103",nonmeat,true);Check(Apply(foreign)==0&&Action(foreign).gameObject.Value==nonmeat,"foreign nonmeat loot remains unchanged");
  var variable=Corpse("Variable_Dead(Clone)104",raw,true);Action(variable).gameObject.UseVariable=true;Check(Apply(variable)==0&&Action(variable).gameObject.Value==raw,"variable-backed loot is not rebound");
  var disabled=Corpse("Disabled_Dead(Clone)105",raw,true);Action(disabled).Enabled=false;Check(Apply(disabled)==0&&Action(disabled).gameObject.Value==raw,"disabled action remains untouched");
  var unknown=Make("meat_unknown_raw");var missing=Corpse("Missing_Dead(Clone)106",unknown,true);Check(Apply(missing)==0&&Action(missing).gameObject.Value==unknown,"missing native cooking mapping preserves original loot");
  GameObject ambiguousCooked;var ambiguousRaw=Raw("dog",out ambiguousCooked);var cooking=ambiguousRaw.GetComponent<PlayMakerFSM>();var another=Make("meat_dog_cooked_mod");cooking.Fsm.States[0].Actions=new FsmStateAction[]{Spawn(ambiguousCooked),Spawn(another)};var ambiguous=Corpse("Ambiguous_Dead(Clone)107",ambiguousRaw,true);Check(Apply(ambiguous)==0&&Action(ambiguous).gameObject.Value==ambiguousRaw,"ambiguous cooking destinations are rejected");
  GameObject modCooked;var modRaw=Raw("insect",out modCooked);var modDestination=Make("meat_insect_cooked_ModChoice");((CreateObject)modRaw.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions[0]).gameObject.Value=modDestination;var modBody=Corpse("Modded_Dead(Clone)108",modRaw,true);Check(Apply(modBody)==1&&Action(modBody).gameObject.Value==modDestination,"current optional-mod cooked mapping is respected");
  Action(plain).Init(plain.GetComponent<PlayMakerFSM>().Fsm.States[0]);var wrongOwner=Corpse("WrongOwner_Dead(Clone)109",raw,true);wrongOwner.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions=plain.GetComponent<PlayMakerFSM>().Fsm.States[0].Actions;Check(Apply(wrongOwner)==0&&Action(plain).gameObject.Value==raw,"foreign-owned shared action cannot be mutated");
  foreach(int amount in new[]{1,2,3,8}){var counted=Corpse("Counted_Dead(Clone)"+amount,raw,true);var f=counted.GetComponent<PlayMakerFSM>();var compare=new IntCompare{integer1=new FsmInt{Value=0},integer2=new FsmInt{Value=amount}};var untouched=new FsmState(f.Fsm){Name="unrelated",Actions=new FsmStateAction[]{compare}};var first=f.Fsm.States[0];f.Fsm.States=new[]{first,untouched};Check(Apply(counted)==1&&ReferenceEquals(f.Fsm.States[1],untouched)&&compare.integer2.Value==amount,"native yield control remains intact: "+amount);var create=Action(counted);create.Init(first);for(int i=0;i<amount;i++){create.OnEnter();var spawned=create.storeObject.Value;owned.Add(spawned);Check(spawned!=null&&spawned.name.StartsWith("meat_dog_cooked",StringComparison.Ordinal),"native CreateObject spawns cooked piece "+i+" of "+amount);}}
  DeferredCook(raw,cooked);Persistence(raw);
 }
 void DeferredCook(GameObject raw,GameObject cooked){
  var cold=Make("Deferred_Dead(Clone)2000");var component=cold.AddComponent<PlayMakerFSM>();component.Reset();component.enabled=false;var fsm=new Fsm{Name="Carcasse"};var state=new FsmState(fsm){Name="butcher",Actions=new FsmStateAction[]{Spawn(raw)}};fsm.States=new[]{state};fsm.StartState="butcher";fsm.SaveActions();typeof(PlayMakerFSM).GetField("fsm",All).SetValue(component,fsm);Check(!fsm.Initialized,"deferred fixture retains genuinely uninitialized native serialized FSM");Mark(cold);Apply(cold);var retryType=assembly.GetType("ChainsawPrototype.FlameCookedHarvestRetry");var retry=retryType==null?null:cold.GetComponent(retryType) as Behaviour;
  Check(retry!=null,"cold owned Carcasse schedules bounded deferred cooked selection");if(retry==null)return;
  fsm.Init(component);Call(retry,"Advance",Time.unscaledTime+.3f);Check(((CreateObject)state.Actions[0]).gameObject.Value==cooked&&!retry.enabled,"deferred selection applies after native owned FSM initialization then stops");
  var nonharvest=Make("Human_Dead(Clone)2001");Mark(nonharvest);Apply(nonharvest);Check(nonharvest.GetComponent(retryType)==null,"nonharvestable marked corpse schedules no retry");
  var abandoned=Make("Unready_Dead(Clone)2002");var pending=abandoned.AddComponent<PlayMakerFSM>();pending.Reset();pending.enabled=false;typeof(PlayMakerFSM).GetField("fsm",All).SetValue(pending,new Fsm{Name="Carcasse"});Mark(abandoned);int timeoutWarnings=0;helper.GetMethod("Apply",All).Invoke(null,new object[]{abandoned,new Action<string>(message=>timeoutWarnings++)});var abandonedRetry=abandoned.GetComponent(retryType) as Behaviour;Check(abandonedRetry!=null,"unready owned corpse receives retry");if(abandonedRetry!=null){for(int i=1;i<=13;i++)Call(abandonedRetry,"Advance",Time.unscaledTime+i*.26f);Check(!abandonedRetry.enabled,"unready cooked selection stops after bounded retry budget");for(int i=14;i<=20;i++)Call(abandonedRetry,"Advance",Time.unscaledTime+i);Check(timeoutWarnings==1,"expired deferred selection warns once and never resumes work");}
  var destroyed=Make("DestroyedDeferred_Dead(Clone)2003");var waiting=destroyed.AddComponent<PlayMakerFSM>();waiting.Reset();waiting.enabled=false;typeof(PlayMakerFSM).GetField("fsm",All).SetValue(waiting,new Fsm{Name="Carcasse"});Mark(destroyed);Apply(destroyed);var destroyedRetry=destroyed.GetComponent(retryType);DestroyImmediate(destroyed);Check(destroyedRetry==null,"destroying corpse cleans its owned deferred component");
 }
 ES3Settings Disk(string name){var s=new ES3Settings(Path.Combine(host,name+".es3"),ES3.Location.File);s.encryptionType=ES3.EncryptionType.None;s.compressionType=ES3.CompressionType.None;return s;}
 void Persistence(GameObject raw){var listGo=Make("HarvestSaveList");var list=listGo.AddComponent<PlayMakerArrayListProxy>();Call(list,"Awake");Set(pack,"chainsawSaveItems",list);var marked=Corpse("Persist_Dead(Clone)1000",raw,true,777);var plain=Corpse("Plain_Dead(Clone)1001",raw,false,778);var outside=Corpse("Outside_Dead(Clone)1002",raw,true,779);list.arrayList.Add(marked);list.arrayList.Add(plain);Check(marked.scene.IsValid()&&marked.scene.isLoaded,"save fixture lives in an explicit loaded scene");Logger.LogInfo("SAVE INPUT: sceneValid="+marked.scene.IsValid()+" loaded="+marked.scene.isLoaded+" marker="+(marked.GetComponent(marker)!=null)+" prefabId="+marked.GetComponent<ES3Prefab>().prefabId+" listCount="+list.arrayList.Count);var settings=Disk("harvest-slot-a");ES3.Save<int>("Foreign.Sentinel",42,settings);Call(pack,"SaveBurntCorpses",settings);Check(ES3.KeyExists(Key,settings),"owned corpse metadata key reaches native ES3 disk");var json=ES3.Load<string>(Key,settings);File.WriteAllText(Path.Combine(host,"initial-saved-metadata.json"),json);Check(json.Contains("Persist_Dead(Clone)1000")&&json.Contains("777")&&!json.Contains("Plain_Dead")&&!json.Contains("Outside_Dead"),"disk metadata includes only marked live native-list members");Check(ES3.Load<int>("Foreign.Sentinel",settings)==42,"saving preserves foreign slot key");
  Call(pack,"LoadBurntCorpses",settings);Check((float)pack.GetType().GetField("pendingBurntCorpseDeadline",All).GetValue(pack)==0f,"loading metadata does not start the post-load readiness deadline");DestroyImmediate(marked);list.arrayList.Clear();var restored=Corpse("Persist_Dead(Clone)1000",raw,false,777);list.arrayList.Add(restored);list.arrayList.Add(plain);Call(pack,"RestorePendingBurntCorpses");Check(restored.GetComponent(marker)!=null&&Action(restored).gameObject.Value.name=="meat_dog_cooked","load restores marker and cooked selection by exact name and prefab ID");Check(plain.GetComponent(marker)==null&&Action(plain).gameObject.Value==raw,"load leaves unmarked neighbor untouched");Call(pack,"RestorePendingBurntCorpses");Check(restored.GetComponents(marker).Length==1,"repeated pending restore adds no duplicate marker");
  Call(pack,"LoadBurntCorpses",settings);DestroyImmediate(restored);list.arrayList.Clear();var wrong=Corpse("Persist_Dead(Clone)1000",raw,false,999);list.arrayList.Add(wrong);Call(pack,"RestorePendingBurntCorpses");Check(wrong.GetComponent(marker)==null,"matching name with different prefab identity is rejected");
  var match=Corpse("Persist_Dead(Clone)1000",raw,false,777);var duplicate=Corpse("Persist_Dead(Clone)1000",raw,false,777);list.arrayList.Add(match);list.arrayList.Add(duplicate);Call(pack,"RestorePendingBurntCorpses");Check(match.GetComponent(marker)==null&&duplicate.GetComponent(marker)==null,"ambiguous native list identity never marks either corpse");
  Call(pack,"ClearPendingBurntCorpses");list.arrayList.Remove(duplicate);Call(pack,"RestorePendingBurntCorpses");Check(match.GetComponent(marker)==null,"scene cleanup discards pending corpse attribution");
  Call(pack,"LoadBurntCorpses",settings);Call(pack,"LoadBurntCorpses",Disk("harvest-slot-b"));Call(pack,"RestorePendingBurntCorpses");Check(match.GetComponent(marker)==null,"old save without key clears prior-slot pending records");
  ES3.Save<string>(Key,"{\"version\":1,\"corpses\":[{\"name\":\"Missing_Dead(Clone)9000\",\"prefabId\":777}]}",settings);Call(pack,"LoadBurntCorpses",settings);Call(pack,"SaveBurntCorpses",settings);Check(!ES3.Load<string>(Key,settings).Contains("Missing_Dead"),"saving drops stale unmatched pending identity");for(int i=0;i<13;i++)Call(pack,"RestorePendingBurntCorpses");var pendingField=pack.GetType().GetField("pendingBurntCorpses",All);Check(((IList)pendingField.GetValue(pack)).Count==0,"unmatched corpse restoration expires after finite readiness attempts");if(((IList)pendingField.GetValue(pack)).Count!=0)return;
  ES3.Save<string>(Key,"{\"version\":1,\"corpses\":[{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":777}]}",settings);Call(pack,"LoadBurntCorpses",settings);Set(pack,"chainsawLoadingUntil",Time.unscaledTime+10f);for(int i=0;i<20;i++)Call(pack,"RestorePendingBurntCorpses");Check(((IList)pendingField.GetValue(pack)).Count==1&&match.GetComponent(marker)==null,"world loading pauses pending corpse work and readiness budget");Call(pack,"SaveBurntCorpses",settings);Check(ES3.Load<string>(Key,settings).Contains("Persist_Dead(Clone)1000"),"saving before restore preserves pending exact identity present in native list");Set(pack,"chainsawLoadingUntil",0f);list.arrayList.Remove(match);Call(pack,"RestorePendingBurntCorpses");list.arrayList.Add(match);Set(pack,"pendingBurntCorpseDeadline",Time.unscaledTime-1f);Call(pack,"RestorePendingBurntCorpses");Check(((IList)pendingField.GetValue(pack)).Count==0&&match.GetComponent(marker)==null,"pending corpse restoration expires at unscaled deadline after readiness begins");
  foreach(var payload in new[]{"{}","{\"version\":1}","{\"version\":2,\"corpses\":[{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":777}]}","{\"version\":1,\"corpses\":[null,{\"name\":null,\"prefabId\":777},{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":0}]}","{broken"}){ES3.Save<string>(Key,payload,settings);Call(pack,"LoadBurntCorpses",settings);Call(pack,"RestorePendingBurntCorpses");Check(match.GetComponent(marker)==null,"invalid, unsupported or partial metadata is a no-op: "+payload);}
  ES3.Save<string>(Key,"{\"version\":1,\"corpses\":[{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":777},{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":777}]}",settings);Call(pack,"LoadBurntCorpses",settings);Call(pack,"RestorePendingBurntCorpses");Check(match.GetComponent(marker)==null,"duplicate metadata identity is rejected");
  ES3.Save<string>(Key,"{\"version\":1,\"corpses\":[{\"name\":\"Persist_Dead(Clone)1000\",\"prefabId\":777}]}",settings);Call(pack,"LoadBurntCorpses",settings);Set(pack,"chainsawLoadingUntil",Time.unscaledTime+1000f);float afterSlowLoad=Time.unscaledTime+60f;Call(pack,"AdvanceBurntCorpseRestore",afterSlowLoad);Check((float)pack.GetType().GetField("pendingBurntCorpseDeadline",All).GetValue(pack)==0f,"sixty seconds behind the native loading gate consumes no readiness time");Set(pack,"chainsawLoadingUntil",0f);Call(pack,"AdvanceBurntCorpseRestore",afterSlowLoad);Check(match.GetComponent(marker)!=null&&Action(match).gameObject.Value.name=="meat_dog_cooked","exact burnt corpse restores after a slow native load exceeds thirty seconds");
  list.arrayList.Clear();Call(pack,"SaveBurntCorpses",settings);Check(!ES3.Load<string>(Key,settings).Contains("Persist_Dead"),"saving after corpse destruction removes stale saved records");
 }
}









